/* DS1 (7 Oct 2026) — the deployment system, live in the allocation tool. Turns live prices into every part's reading, reads the engine,
   and draws: the reading in points, the pie on today's account, the dips, the levels and the reset tracker per name, the stretch rules.
   Reads only: GETs to the chart API through the page's own rewrites (/candles-multi, /quotes, /macro, /geiger) and one static file
   (study/ds1/data/ds1-live.json). No write, no key, no table.

   WHAT IS LIVE AND WHAT IS NOT
     live every read      every fund and name (the chart API's /quotes), the VIX with its session high and low (/macro), today's own high
                          and low per symbol (the chart API's 30-minute bars), the Hub's own Geiger for the indices and the names (/geiger)
     daily closes         the last 540 sessions of all 26 symbols (/candles-multi, two requests of 13) — on load, on a new day, after the close
     static, dated        the model, each name's usual cool-off, the trim odds, the named pivots, HYG's payout list, FRED's spread (ds1-live.json)

   THE LIVENESS RULE (Alan, 3 Oct: "a little bit wrong rather than a little bit old")
     · a read that fails never blanks the panel: the last reading stays, with its age and the cause of the failed try;
     · a symbol with no live price keeps its last close and is named with that close's date; a part with no reading does not vote and says so;
     · the age is always on screen and ticks every second; nothing here can hold a reading back.

   WHEN IT READS
     on load · every 60 seconds while New York is open (09:30–16:00) · every 5 minutes before the open and after the close (04:00–20:00)
     · once more from 16:10 for the settled daily bars. Not while the tab is hidden; a tab that comes back reads at once if one is due. */
import * as E from "./engine.mjs";

import { DIALS } from "../al9/chain.mjs";

export const DAILY_BARS = 540, FIVE_MIN_BARS = 220, STORE = "al9.assumptions";   // AL9: the dials changed shape (held part, conviction's share, the cap, the band), so a set saved under DS1's key is not read into them
const NONVIX = E.ALL_SYMBOLS.filter((s) => s !== "VIX"), iso = (t) => new Date(t).toISOString().slice(0, 10), clamp = (x, a, b) => Math.max(a, Math.min(b, x));

/* ---------- the clock (New York wall-clock from the browser's own time-zone table) ---------- */
export function nyParts(now = new Date()) { const f = new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", hourCycle: "h23", weekday: "short", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit" });
  const p = Object.fromEntries(f.formatToParts(now).map((x) => [x.type, x.value])); return { date: `${p.year}-${p.month}-${p.day}`, weekday: p.weekday, minutes: +p.hour * 60 + +p.minute, hms: `${p.hour}:${p.minute}:${p.second}`, ms: +now }; }
export const SESSION = { pre: 4 * 60, open: 9 * 60 + 30, close: 16 * 60, afterClose: 16 * 60 + 10, late: 20 * 60, openEverySec: 60, extEverySec: 300 };
export const phaseOf = (now) => (now.weekday === "Sat" || now.weekday === "Sun" ? "closed" : now.minutes >= SESSION.open && now.minutes < SESSION.close ? "open" : now.minutes >= SESSION.pre && now.minutes < SESSION.open ? "pre-market" : now.minutes >= SESSION.close && now.minutes < SESSION.late ? "after hours" : "closed");
/* is a read due? last = nyParts() of the last successful read (null = never) */
export function readDue(now, last) { if (!last) return true; const ph = phaseOf(now); if (ph === "closed") return false; const age = (now.ms - last.ms) / 1000;
  if (ph === "open") return last.date !== now.date || last.minutes < SESSION.open || age >= SESSION.openEverySec;
  if (ph === "after hours" && now.minutes >= SESSION.afterClose && (last.date !== now.date || last.minutes < SESSION.afterClose)) return true;
  return last.date !== now.date || age >= SESSION.extEverySec; }
export const nextReadWords = (now) => { const ph = phaseOf(now); return ph === "open" ? "reads every minute" : ph === "closed" ? "reads again when New York trades" : "reads every 5 minutes outside the session"; };

/* ---------- HYG with its payouts added back (the same chain as study/dm2/live.mjs): after the last payout the file knows, last year's
   ex-dates are repeated with the last known amount; "estimated" counts how many such payouts were assumed ---------- */
export function hygWithPayouts(dates, price, payouts) { const known = new Map(payouts), last = payouts[payouts.length - 1], proj = new Map(); let estimated = 0;
  if (last) for (const [d] of payouts) { const next = (+d.slice(0, 4) + 1) + d.slice(4); if (next <= last[0]) continue; const at = dates.find((x) => x >= next); if (at && !known.has(at) && !proj.has(at)) { proj.set(at, last[1]); estimated++; } }
  const tr = []; let prev = null, cur = null; for (let i = 0; i < dates.length; i++) { const p = price[i]; if (p == null) { tr.push(null); continue; } if (prev == null) cur = p; else cur *= (p + (known.get(dates[i]) ?? proj.get(dates[i]) ?? 0)) / prev; prev = p; tr.push(cur); } return { tr, estimated }; }

/* ---------- the chart API's answers → one aligned series ---------- */
export function alignBars(candles) { const spy = (candles.SPY?.series || []).filter((b) => b && b.c != null), dates = spy.map((b) => iso(b.t)), bars = {}, absent = [];
  for (const s of E.ALL_SYMBOLS) { const ser = (candles[s]?.series || []).filter((b) => b && b.c != null); if (!ser.length) { absent.push(s); bars[s] = null; continue; } const m = new Map(ser.map((b) => [iso(b.t), b])); let cur = null; const c = [], h = [], l = [];
    for (const d of dates) { const b = m.get(d); if (b) { cur = b.c; c.push(b.c); h.push(Math.max(b.h ?? b.c, b.c)); l.push(Math.min(b.l ?? b.c, b.c)); } else { c.push(cur); h.push(cur); l.push(cur); } } bars[s] = { c, h, l }; }
  return { dates, bars, absent }; }
/* a quote's price for the session: the session's own completed close once the provider has it, else the live price */
export const quotePrice = (q) => (!q ? null : q.today_session_close != null && q.today_session_close_state && q.today_session_close_state !== "ABSENT" ? q.today_session_close : q.price ?? null);
/* today's own high and low per symbol from the 30-minute bars of the regular session (09:30–16:00 New York) */
export function sessionRanges(intraday, session) { const out = {}; if (!intraday) return out; const f = new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" });
  for (const [s, o] of Object.entries(intraday)) { let hi = -Infinity, lo = Infinity; for (const b of (o && o.series) || []) { if (!b || b.h == null || b.l == null) continue; const p = Object.fromEntries(f.formatToParts(new Date(b.t)).map((x) => [x.type, x.value])), min = +p.hour * 60 + +p.minute; if (`${p.year}-${p.month}-${p.day}` !== session || min < SESSION.open || min >= SESSION.close) continue; if (b.h > hi) hi = b.h; if (b.l < lo) lo = b.l; } if (isFinite(hi)) out[s] = { hi, lo }; } return out; }
/* add today's live prices as one more bar when the session is newer than the last settled daily bar */
export function withLive(S0, quotes, macro, ranges = {}) { const q = quotes || {}, session = q.SPY?.price_session_et, spy = quotePrice(q.SPY), lastBar = S0.dates[S0.dates.length - 1], k0 = S0.dates.length - 1;
  if (!session || spy == null || session <= lastBar) return { S: S0, live: false, session: lastBar, missing: [], noRange: [], prices: Object.fromEntries(E.ALL_SYMBOLS.map((s) => [s, S0.bars[s] ? S0.bars[s].c[k0] : null])), prev: Object.fromEntries(E.ALL_SYMBOLS.map((s) => [s, S0.bars[s] ? S0.bars[s].c[k0 - 1] : null])) };
  const bars = {}, missing = [], noRange = [], prices = {}, prev = {}, vq = macro?.VIX?.quote;
  for (const s of E.ALL_SYMBOLS) { const b = S0.bars[s]; if (!b) { bars[s] = null; prices[s] = null; continue; } const last = b.c[k0]; let p, hi, lo;
    if (s === "VIX") { const ok = vq && vq.price != null && (!vq.session_et || vq.session_et === session); p = ok ? vq.price : null; hi = ok ? vq.day_high : null; lo = ok ? vq.day_low : null; } else { p = quotePrice(q[s]); const r = ranges[s]; hi = r ? r.hi : null; lo = r ? r.lo : null; }
    if (p == null) { missing.push(s); p = last; hi = lo = last; } else if (hi == null || lo == null) { noRange.push(s); hi = Math.max(hi ?? p, p); lo = Math.min(lo ?? p, p); }
    bars[s] = { c: b.c.concat(p), h: b.h.concat(Math.max(hi, p)), l: b.l.concat(Math.min(lo, p)) }; prices[s] = p; prev[s] = last; }
  return { S: { dates: S0.dates.concat(session), bars }, live: true, session, missing, noRange, prices, prev }; }

/* ---------- the assumptions: every one an editable input with its baseline ---------- */
export const BASE_ACCOUNT = { cash: 452050, shares: { MU: 50, NBIS: 70 }, asOf: "7 Oct 2026, 13:05 New York (IBKR): about $520K, 50 Micron, 70 Nebius, the rest cash" };
/* AL9 (7 Oct): the dials are the chain's (study/al9/chain.mjs DIALS) — the held part and the tactical part, conviction's share of what is
   invested and its lift, Micron's part of conviction, the cap, the breakout band, the minutes averaged, the first buy's share. DS1's three
   fixed slots (core 45, Micron 20, Nebius 5) are what those dials come to when fully invested with no lift; its average over days is gone
   (Alan: no three-day averaging — the number is smoothed over the last hour only). */
export function baseline(base) { const d = (base && base.defaults) || E.DEFAULTS; return { ...DIALS, coreWeights: { ...d.coreWeights }, dips: d.dips.slice(), dipCredit: d.dipCredit || 0, spyPerQqq: d.spyPerQqq, beta: { ...((base && base.beta) || E.BETA_QQQ) }, count: {}, cash: BASE_ACCOUNT.cash, shares: { ...BASE_ACCOUNT.shares } }; }
/* DS1's own pie (E.pie) wants three fixed slots: the held part split at the baseline conviction share. Only its totals are read now
   (invested, tactical, held) and they do not depend on the split. */
export const ds1Shape = (A) => { const c = clamp(+A.convShare, 0, 100) / 100, m = clamp(+A.micronOfConv, 0, 100) / 100; return { ...A, corePct: A.heldPct * (1 - c), micronPct: A.heldPct * c * m, nebiusPct: A.heldPct * c * (1 - m) }; };
export function loadAssumptions(base, store = typeof localStorage !== "undefined" ? localStorage : null) { const A = baseline(base); try { const s = store && JSON.parse(store.getItem(STORE) || "null"); if (s && typeof s === "object") for (const k of Object.keys(A)) if (s[k] != null) A[k] = typeof A[k] === "object" && !Array.isArray(A[k]) ? { ...A[k], ...s[k] } : s[k]; } catch (e) { /* a broken saved value falls back to the baseline */ } return A; }
export const saveAssumptions = (A, store = typeof localStorage !== "undefined" ? localStorage : null) => { try { store && store.setItem(STORE, JSON.stringify(A)); } catch (e) { /* private mode: the inputs still work for this visit */ } };

/* ---------- the reading, with any light the user has switched on counted ---------- */
export function readWith(inputs, model, count = {}) { const r = E.readSystem(inputs, model); let add = 0; for (const l of r.lights) if (count[l.key] && !l.missing) { add += l.points; l.counted = true; } if (add) { r.raw = +(r.raw + add).toFixed(1); r.reading = +clamp(r.raw, 0, 100).toFixed(1); } r.lightsCounted = add; return r; }

/* ---------- everything the panel shows, from one set of prices ---------- */
export function view({ base, candles, quotes, macro, intraday, geiger, A }) {   // bars5 (AL9) stays on the state: the panel reads it there
  const S0 = alignBars(candles); if (S0.dates.length < 260) throw new Error("the chart API served " + S0.dates.length + " daily bars; 260 are needed");
  const session0 = quotes?.SPY?.price_session_et, L = withLive(S0, quotes, macro, sessionRanges(intraday, session0)), S = L.S, k = S.dates.length - 1, model = base.model;
  const hyg = S.bars.HYG ? hygWithPayouts(S.dates, S.bars.HYG.c, base.hygPayouts || []) : { tr: null, estimated: 0 }, RD = E.allReadings(S, hyg.tr), X = RD.X;
  const rd = (i) => readWith(E.inputsAt(X, i), model, A.count), now = rd(k), prior = [1, 2, 3, 4].map((n) => ({ date: S.dates[k - n], reading: rd(k - n).reading }));
  const nAvg = 1, avg = (r0) => r0, deployed = now.reading, AP = ds1Shape(A);   // AL9: no average over days
  /* the account, at live prices */
  const positions = {}; for (const [s, n] of Object.entries(A.shares || {})) if (n > 0 && L.prices[s] != null) positions[s] = { shares: +n, price: L.prices[s] };
  const nlv = (+A.cash || 0) + Object.values(positions).reduce((a, p) => a + p.shares * p.price, 0), account = { nlv, positions };
  const pieNow = E.pie(deployed, AP, account);
  /* the dips: SPY and QQQ fall together from here; everything else moves the way it usually has */
  const scn = base.scn, idx = { spy: L.prices.SPY, qqq: L.prices.QQQ, qqqLevels: {}, spyLevels: {} };
  for (const [nm, a] of [["21-day", "s21"], ["50-day", "s50"], ["100-day", "s100"], ["200-day", "s200"]]) { idx.qqqLevels[nm] = RD.ind.QQQ[a][k]; idx.spyLevels[nm] = RD.ind.SPY[a][k]; }
  const lines = (base.lines && base.lines.names) || {}, names = E.NAMES.map((s) => { const o = RD.ind[s], price = L.prices[s]; if (!o || price == null) return { sym: s, absent: true };
    const cool = E.coolNow(o, S.dates, k), usual = (base.cool && (base.cool[s] || base.cool.pooled)) || null, g = geiger && geiger[s];
    /* where this name's own usual cool-off would take it from the top of this leg — one more level, when it is still under the price */
    const usualAt = usual && cool.push && !cool.gaveUp && usual.dipPct.med != null ? cool.pushClose * (1 + usual.dipPct.med / 100) : null;
    /* the four averages and the nearest four named pivots under the price — and the usual cool-off's level always, however many pivots sit above it */
    const levels = E.levelsFor(s, o, k, price, idx, lines[s] || [], A.beta[s], A.spyPerQqq, 4);
    if (usualAt != null && usualAt < price) { const u = E.levelsFor(s, o, k, price, idx, [{ id: "usual cool-off", level: usualAt, kind: "usual" }], A.beta[s], A.spyPerQqq, 1).find((r) => r.kind === "usual"); if (u) { u.note = `${usual.dipPct.med.toFixed(1)}% from its top of ${cool.pushClose >= 1000 ? cool.pushClose.toFixed(0) : cool.pushClose.toFixed(2)}`; levels.push(u); levels.sort((x, y) => y.level - x.level); } }
    const st = usual ? { wr: E.resetState(cool.lowWr, usual.wr), rsi: E.resetState(cool.lowRsi, usual.rsi), mom: E.resetState(cool.lowMom, usual.mom) } : null;
    return { sym: s, price, chgPct: L.prev[s] ? (price / L.prev[s] - 1) * 100 : null, beta: A.beta[s], role: E.CORE.includes(s) ? "core #" + (E.CORE.indexOf(s) + 1) : E.CONVICTION.includes(s) ? "conviction" : "watch", levels, cool, usual, st, hub: g ? { trend: g.trend, momentum: g.momentum, composite: g.composite } : null, gauges: { rsi: o.rsi[k], wr: o.wr[k], mom: o.mom[k], trend: o.trend[k] }, hasLines: !!(lines[s] && lines[s].length), state: nameState(cool, usual, st) }; });
  const dips = A.dips.map((x) => { const rdOn = (holds) => { const d = E.dipSeries(S, hyg.tr, +x, scn, A.beta, holds), R = E.allReadings(d.S, d.hygTR); return { r: readWith(E.inputsAt(R.X, k), model, A.count), vix: d.S.bars.VIX ? d.S.bars.VIX.c[k] : null }; };
    const calm = rdOn(true), usual = rdOn(false), main = A.dipCredit ? usual : calm, dep = avg(main.r.reading), p = E.pie(dep, AP, account);
    /* the add levels each name would touch on the way: the deepest one is named, the count of the others follows it */
    const reached = names.filter((n) => !n.absent).map((n) => { const after = n.price * (1 - (n.beta * x) / 100), hit = n.levels.filter((lv) => lv.below && lv.level >= after); return hit.length ? { sym: n.sym, ids: hit.map((h) => h.id), deepest: hit[hit.length - 1].id, after } : null; }).filter(Boolean);
    return { dipPct: +x, reading: main.r.reading, readingCalm: calm.r.reading, readingCreditSells: usual.r.reading, deployed: dep, pie: p, spy: idx.spy * (1 - x / 100), qqq: idx.qqq * (1 - x / 100), vix: main.vix, reached, families: main.r.families }; });
  /* the plain facts beside each part */
  const vixYear = S.bars.VIX ? S.bars.VIX.c.slice(Math.max(0, k - 251), k + 1).filter((v) => v != null).sort((a, b) => a - b) : [], q = (p) => (vixYear.length ? vixYear[Math.min(vixYear.length - 1, Math.round(((vixYear.length - 1) * p) / 100))] : null);
  const cnt = (list, a) => { let n = 0, up = 0; for (const s of list) { const o = RD.ind[s]; if (!o || o.c[k] == null || o[a][k] == null) continue; n++; if (o.c[k] > o[a][k]) up++; } return { n, up }; };
  let hygLow = null; for (let i = Math.max(0, k - 15); i <= k; i++) if (X.hygRsi[i] != null && (hygLow == null || X.hygRsi[i] < X.hygRsi[hygLow])) hygLow = i;
  const iefMove = S.bars.IEF && k >= E.CREDIT_WINDOW ? (S.bars.IEF.c[k] / S.bars.IEF.c[k - E.CREDIT_WINDOW] - 1) * 100 : null, hygMove = hyg.tr && k >= E.CREDIT_WINDOW ? (hyg.tr[k] / hyg.tr[k - E.CREDIT_WINDOW] - 1) * 100 : null;
  const facts = { spyRsi: RD.ind.SPY.rsi[k], qqqRsi: RD.ind.QQQ.rsi[k], spyWr: RD.ind.SPY.wr[k], qqqWr: RD.ind.QQQ.wr[k], hub: { SPY: geiger && geiger.SPY, QQQ: geiger && geiger.QQQ },
    vix: { price: L.prices.VIX, high: S.bars.VIX ? S.bars.VIX.h[k] : null, pct: X.vixPct[k], hiPct: X.vixHiPct[k], p80: q(80), p90: q(90), state: X.vixPct[k] >= 80 ? "closed above" : X.vixHiPct[k] >= 80 ? "touched" : "calm" },
    br50: cnt(E.BREADTH, "s50"), br200: cnt(E.BREADTH, "s200"), ld21: cnt(E.CORE, "s21"), ld50: cnt(E.CORE, "s50"),
    credit: { hygRsi: X.hygRsi[k], hygWr: X.hygWr[k], own: X.creditOwn[k], hygMove, ratesLeg: iefMove == null ? null : E.RATES_SHARE * iefMove, low: hygLow == null ? null : { date: S.dates[hygLow], rsi: X.hygRsi[hygLow] }, payoutsEstimated: hyg.estimated, spread: base.credit && base.credit.spread } };
  const stretch = E.stretchNow(E.stretchCtx(RD, S), k, now.reading);
  /* AL9: the last year of daily market readings by the same sum (the stored history ends at its own last day; these carry it to today),
     and the series itself, so the panel can work the reading out at any five-minute price of today */
  const t0 = Math.max(260, k - 260), tail = { dates: S.dates.slice(t0, k + 1), reading: [], spy: S.bars.SPY.c.slice(t0, k + 1), live: L.live }; for (let i = t0; i <= k; i++) tail.reading.push(i === k ? now.reading : rd(i).reading);
  return { S, k, hygTr: hyg.tr, tail, session: L.session, live: L.live, lastBar: S0.dates[S0.dates.length - 1], missing: L.missing, noRange: L.noRange, absent: S0.absent, inputs: E.inputsAt(X, k), reading: now, deployed, prior, nAvg, odds: E.oddsAt(now.reading, model), oddsAny: model.oddsAny, account, pie: pieNow, dips, names, idx, facts, stretch, modelAsOf: base.asOf }; }
/* one line for where a name stands in its cool-off (the Williams is the fast gauge, so it leads the sentence) */
export function nameState(c, u, st) { if (!c || !c.push) return { word: "NO PUSH IN THE PAST YEAR", tone: "" }; if (c.atHigh) return { word: "AT ITS HIGH — no cool-off yet", tone: "hot" };
  if (!st) return { word: "COOLING", tone: "" };
  const deep = !!(u && u.dipPct && c.dipPct < 2 * u.dipPct.q25), w = st.wr.state, r = st.rsi.state; let word, tone;
  if (w === "not yet") { word = "COOLING — Williams not reset yet"; tone = "hot"; }
  else { word = w === "fully reset" && r === "fully reset" ? "FULLY RESET" : r !== "not yet" ? "RESET" : "WILLIAMS RESET — RSI not yet"; tone = "ok"; word += c.wr != null && u.wr && c.wr <= u.wr.q75 ? " · in the zone now" : " · turned back up"; }
  if (deep) word += " · a deeper fall than its cool-offs"; else if (c.gaveUp) word += " · no new high in " + c.sessions + " sessions"; return { word, tone: deep ? "deep" : tone }; }

/* ---------- the fetches (the page passes its own apiGet; a study page or a test passes its own) ---------- */
export async function fetchDaily(getApi) { const half = Math.ceil(E.ALL_SYMBOLS.length / 2), parts = [E.ALL_SYMBOLS.slice(0, half), E.ALL_SYMBOLS.slice(half)];   // the chart API serves at most 25 symbols per request at this depth
  const rs = await Promise.all(parts.map((p) => getApi(`/candles-multi?symbols=${p.join(",")}&tf=1d&limit=${DAILY_BARS}`))); const candles = {}; for (const j of rs) Object.assign(candles, (j && j.candles) || {}); if (!candles.SPY) throw new Error("no daily bars"); return candles; }
export async function fetchLive(getApi) { const [q, m, g, h] = await Promise.all([getApi(`/quotes?symbols=${NONVIX.join(",")}`), getApi("/macro").catch(() => null), getApi(`/geiger?symbols=${[...E.INDEX, ...E.NAMES].join(",")}`).catch(() => null), getApi(`/candles-multi?symbols=${NONVIX.join(",")}&tf=30m&limit=16`).catch(() => null)]);
  const f = await getApi(`/candles-multi?symbols=SPY,QQQ,HYG,IEF&tf=5m&limit=${FIVE_MIN_BARS}`).catch(() => null);   // AL9: the number through the day — a failed read leaves the last path on screen
  return { quotes: (q && q.quotes && !Array.isArray(q.quotes) ? q.quotes : {}) || {}, macro: (m && m.macro) || null, geiger: (g && g.symbols) || null, intraday: (h && h.candles) || null, bars5: f && f.candles ? Object.fromEntries(Object.entries(f.candles).map(([sym, o]) => [sym, (o && o.series) || []])) : null, generated: q && q.generated_utc }; }

/* ---------- the picture ---------- */
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
const MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]; export const day = (d) => (d ? +d.slice(8, 10) + " " + MON[+d.slice(5, 7) - 1] : "—"), dayY = (d) => day(d) + " " + d.slice(0, 4);
const f0 = (x) => (x == null || !isFinite(x) ? "—" : x.toFixed(0)), f1 = (x) => (x == null || !isFinite(x) ? "—" : x.toFixed(1)), f2 = (x) => (x == null || !isFinite(x) ? "—" : x.toFixed(2));
const sg = (x, d = 0) => (x == null || !isFinite(x) ? "—" : (x > 0 ? "+" : x < 0 ? "−" : "") + Math.abs(x).toFixed(d)), px = (x) => (x == null || !isFinite(x) ? "—" : x >= 1000 ? x.toLocaleString("en-US", { maximumFractionDigits: 0 }) : x.toFixed(2));
