    out.push(`<div class="famb" data-family="${fam}"><div class="fam"><span>${esc(name.toUpperCase())}</span><b class="${any ? tone(counted) : "dim"}">${any ? sg(counted) + " counted" : "shown, not counted"}</b></div>`);
